(function () {
const DN = window.DN;
const NAV_SEARCH_SELECTOR = 'button#dn-nav-search,button[aria-label="搜尋"],button[aria-label="Search"]';
DN.KOFI_URL = 'https://ko-fi.com/expertise88864';
DN.JKO_URL = 'https://service.jkopay.com/r/transfer?j=Transfer:901070305';
DN.SUPPORT_PROVIDER = '街口支付';
function supportPageUrl() {
return DN.detectLang() === 'en' && DN.SUPPORT_URL === '/support' ? '/en/support' : DN.SUPPORT_URL;
}
function coffeeIcon(size, hidden) {
var namespace = 'http://www.w3.org/2000/svg';
var icon = document.createElementNS(namespace, 'svg');
var attributes = { width: size, height: size, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', 'stroke-width': '2.2', 'stroke-linecap': 'round', 'stroke-linejoin': 'round' };
Object.keys(attributes).forEach(function (name) { icon.setAttribute(name, attributes[name]); });
if (hidden) icon.setAttribute('aria-hidden', 'true');
['M18 8h1a4 4 0 0 1 0 8h-1', 'M2 8h16v9a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4V8z'].forEach(function (d) {
var shape = document.createElementNS(namespace, 'path');
shape.setAttribute('d', d); icon.appendChild(shape);
});
[6, 10, 14].forEach(function (x) {
var line = document.createElementNS(namespace, 'line');
line.setAttribute('x1', x); line.setAttribute('y1', '1');
line.setAttribute('x2', x); line.setAttribute('y2', '4'); icon.appendChild(line);
});
return icon;
}
function textBlock(tag, style, zh, en, parent) {
var node = document.createElement(tag);
node.style.cssText = style;
node.setAttribute('data-zh', zh); node.setAttribute('data-en', en);
node.textContent = zh; parent.appendChild(node);
return node;
}
DN.injectBMCFooter = function () {
if (!DN.SUPPORT_URL) return;
if (document.getElementById('dn-bmc-footer')) return;
var footer = document.querySelector('footer');
if (!footer) return;
var section = document.createElement('section');
section.id = 'dn-bmc-footer';
section.className = 'max-w-3xl mx-auto px-5 sm:px-8 my-6';
section.style.cssText = 'text-align:center';
var card = document.createElement('div');
card.style.cssText = 'background:#fff;border:1px solid var(--border,#e7e2d8);border-radius:18px;padding:22px 24px;box-shadow:0 1px 2px rgba(15,23,42,.04), 0 14px 30px -18px rgba(77,99,88,.18)';
section.appendChild(card);
textBlock('div', 'font-size:11px;text-transform:uppercase;letter-spacing:.22em;color:#0e7c86;font-weight:700;margin-bottom:6px', '如果這個網站對您有幫助', 'If this site has helped you', card);
textBlock('h3', "font-family:'Noto Serif TC',Georgia,serif;font-size:20px;font-weight:700;color:#0f172a;margin:0 0 8px", '請我喝杯咖啡 ☕', 'Buy me a coffee ☕', card);
var paragraph = textBlock('p', 'font-size:13px;color:#5e574e;line-height:1.85;margin:0 auto 14px;max-width:540px',
'本網站<strong>無業配、無贊助</strong>，所有衛教文章與量表計算器都<strong>免費</strong>。本贊助為讀者自願性的內容打賞，<strong>非醫療服務費用</strong>，不涉及任何醫療諮詢、診斷或治療。',
'No ads, no sponsorships. All articles and calculators are free. This support is a voluntary content tip, not a medical-service fee, and does not involve any medical consultation, diagnosis, or treatment.', card);
paragraph.textContent = '';
['本網站', '無業配、無贊助', '，所有衛教文章與量表計算器都', '免費', '。本贊助為讀者自願性的內容打賞，', '非醫療服務費用', '，不涉及任何醫療諮詢、診斷或治療。'].forEach(function (text, index) {
if (index % 2) {
var strong = document.createElement('strong'); strong.textContent = text; paragraph.appendChild(strong);
} else paragraph.appendChild(document.createTextNode(text));
});
var footerLink = document.createElement('a');
footerLink.setAttribute('href', supportPageUrl());
footerLink.setAttribute('data-bmc-footer-link', '');
footerLink.style.cssText = 'display:inline-flex;align-items:center;gap:8px;padding:10px 22px;border-radius:9999px;background:#0e7c86;color:#fff;text-decoration:none;font-size:14px;font-weight:700;border:1px solid #0e7c86;box-shadow:0 4px 12px -4px rgba(14,124,134,.4);transition:background .15s';
footerLink.appendChild(coffeeIcon(16, false));
textBlock('span', '', '贊助本站', 'Support this site', footerLink);
card.appendChild(footerLink);
DN.applyTextOnly(DN.detectLang(), section);
footer.parentNode.insertBefore(section, footer);
if (typeof gtag === 'function') {
var link = section.querySelector('[data-bmc-footer-link]');
if (link) link.addEventListener('click', function () {
try { gtag('event', 'support_click', { source: 'footer', page_path: location.pathname }); } catch (e) {}
});
}
};
DN.injectSupportUI = function () {
DN.injectBMCFooter();
if (!DN.SUPPORT_URL) return;
if (document.getElementById('dn-nav-support')) return;
if (document.getElementById('dn-bmc-header')) return;
var headerInner = document.querySelector('header.sticky .h-16 > div:last-child');
if (!headerInner) return;
if (!document.getElementById('dn-bmc-header-css')) {
var supportStyle = document.createElement('style');
supportStyle.id = 'dn-bmc-header-css';
supportStyle.textContent =
'.dn-bmc-header-link:hover,.dn-bmc-header-link:focus-visible{' +
'background:#eaf6f3!important;color:#0e7c86!important;outline:none}';
document.head.appendChild(supportStyle);
}
var a = document.createElement('a');
a.id = 'dn-bmc-header';
a.className = 'dn-bmc-header-link';
a.href = supportPageUrl();
a.setAttribute('aria-label', '支持作者');
a.setAttribute('data-zh-aria-label', '支持作者');
a.setAttribute('data-en-aria-label', 'Support the author');
a.style.cssText =
'display:inline-flex;align-items:center;gap:5px;padding:6px 12px;border-radius:9999px;' +
'background:transparent;color:#0c5159;text-decoration:none;' +
'font-size:12px;font-weight:600;border:1px solid #a7d8ce;' +
'transition:background .15s,color .15s';
a.appendChild(coffeeIcon(13, true));
textBlock('span', '', '支持作者', 'Buy me a coffee', a).className = 'hidden sm:inline';
DN.applyTextOnly(DN.detectLang(), a);
var searchBtn = headerInner.querySelector(NAV_SEARCH_SELECTOR);
if (searchBtn && searchBtn.parentNode === headerInner) {
searchBtn.insertAdjacentElement('afterend', a);
} else {
var langSel = headerInner.querySelector('#langToggle');
if (langSel) headerInner.insertBefore(a, langSel);
else headerInner.appendChild(a);
}
if (typeof gtag === 'function') {
a.addEventListener('click', function () {
try { gtag('event', 'bmc_click', { source: 'header', page_path: location.pathname }); } catch (e) {}
});
}
};
})();
